# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_width_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int H, int W, int Cin, int Cout,
    bool has_bias
) {
    const int KH = 3;
    const int KW = 7;
    const int pad_h = 1;
    const int pad_w = 3;
    const int TILE_W = 32;
    const int TILE_H = 4;
    const int HALO_H = 2;
    const int HALO_W = 6;
    const int SMEM_H = TILE_H + HALO_H;
    const int SMEM_W = TILE_W + HALO_W;

    __shared__ float smem[SMEM_H * SMEM_W];

    int w_base = blockIdx.x * TILE_W;
    int h_base = blockIdx.y * TILE_H;
    int nco = blockIdx.z;
    int n = nco / Cout;
    int co = nco % Cout;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int local_w = threadIdx.x;
    int local_h = threadIdx.y;

    float acc = has_bias ? bias[co] : 0.0f;

    for (int ci = 0; ci < Cin; ++ci) {
        for (int load_idx = tid; load_idx < SMEM_H * SMEM_W; load_idx += blockDim.x * blockDim.y) {
            int smem_h = load_idx / SMEM_W;
            int smem_w = load_idx % SMEM_W;
            int in_h = h_base + smem_h - HALO_H / 2;
            int in_w = w_base + smem_w - HALO_W / 2;
            float val = 0.0f;
            if (in_h >= 0 && in_h < H && in_w >= 0 && in_w < W) {
                val = input[((n * Cin + ci) * H + in_h) * W + in_w];
            }
            smem[load_idx] = val;
        }
        __syncthreads();

        int out_h = h_base + local_h;
        int out_w = w_base + local_w;
        if (out_h < H && out_w < W) {
            for (int kh = 0; kh < KH; ++kh) {
                for (int kw = 0; kw < KW; ++kw) {
                    int smem_h = local_h + HALO_H / 2 + pad_h - kh;
                    int smem_w = local_w + HALO_W / 2 + pad_w - kw;
                    if (smem_h >= 0 && smem_h < SMEM_H && smem_w >= 0 && smem_w < SMEM_W) {
                        float in_val = smem[smem_h * SMEM_W + smem_w];
                        float w_val = weight[((ci * Cout + co) * KH + kh) * KW + kw];
                        acc += in_val * w_val;
                    }
                }
            }
        }
        __syncthreads();
    }

    int out_h = h_base + local_h;
    int out_w = w_base + local_w;
    if (out_h < H && out_w < W) {
        output[((n * Cout + co) * H + out_h) * W + out_w] = acc;
    }
