    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(x.dim() == 4, "x must be 4D");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D");
    TORCH_CHECK(x.size(1) == 32, "Cin must be 32");
    TORCH_CHECK(weight.size(0) == 32, "weight.size(0) must be 32");
    TORCH_CHECK(weight.size(1) == 32, "Cout must be 32");
    TORCH_CHECK(weight.size(2) == 3, "KH must be 3");
    TORCH_CHECK(weight.size(3) == 7, "KW must be 7");

    int N = x.size(0);
    int Cin = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int Cout = weight.size(1);

    bool has_bias = bias.has_value();
    if (has_bias) {
        TORCH_CHECK(bias->is_cuda(), "bias must be CUDA tensor");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias->size(0) == Cout, "bias size must match Cout");
    }

    auto output = torch::empty({N, Cout, H, W}, x.options());

    const int TILE_W = 32;
    const int TILE_H = 4;
    dim3 block(TILE_W, TILE_H);
    dim3 grid((W + TILE_W - 1) / TILE_W, (H + TILE_H - 1) / TILE_H, N * Cout);

    conv_transpose2d_width_tiled_kernel<<<grid, block>>>(
